SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Malekö','Skull 77')) = 2 AS fiches,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Malekö"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Skull 77"') FROM `producer_countries` WHERE `id` = 'costarica') AS costarica_annonce,
  (SELECT COUNT(*) FROM `translation_status` WHERE `entite` = 'brands' AND `entite_id` IN ('Malekö','Skull 77')) = 20 AS sceaux,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 249') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
